package generator

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"text/template"
	"unicode"
	"unicode/utf8"
)

const tablesTemplate = `// Code generated by cmd/textcodec-generator. DO NOT EDIT.
// Source: {{.SourceURL}}
//
// This file contains lookup tables derived from Unicode, Inc. mapping files.
// See the NOTICE file in the root of this repository for license information.

package {{.PackageName}}

{{range .Encodings}}
// {{.GoName}}ToUnicode maps {{.GoName}} byte values to Unicode code points.
// Bytes 0x00-0x7F default to ASCII identity mapping; bytes 0x80-0xFF default
// to U+FFFD unless explicitly mapped.
var {{.LowerName}}ToUnicode = [256]rune{
{{- range $i, $r := .ToUnicode}}
{{- if (mod $i 8) | eq 0}}
	{{end}}{{printf "0x%04X" $r}},{{if (mod (add $i 1) 8) | eq 0}} // {{printf "0x%02X" (sub $i 7)}}-{{printf "0x%02X" $i}}{{else}} {{end}}
{{- end}}
}

// {{.LowerName}}FromUnicode maps Unicode code points to {{.GoName}} byte values.
var {{.LowerName}}FromUnicode = map[rune]byte{
{{- range .FromUnicode}}
	{{printf "0x%04X" .Unicode}}: {{printf "0x%02X" .Byte}}, // {{.Name}}
{{- end}}
}
{{end}}
`

const encodingsTemplate = `// Code generated by cmd/textcodec-generator. DO NOT EDIT.
// Source: {{.SourceURL}}
//
// This file contains encoding type definitions derived from Unicode, Inc. mapping files.
// See the NOTICE file in the root of this repository for license information.

package {{.PackageName}}

import (
	"github.com/icha-senpai/note/third_party/forks/external/golang.org/x/text/encoding"
)

{{range .Encodings}}
// {{.GoName}} is the {{$.VendorName}} {{.GoName}} encoding.
var {{.GoName}} encoding.Encoding = &{{.LowerName}}Encoding{}

type {{.LowerName}}Encoding struct{}

func (e *{{.LowerName}}Encoding) NewDecoder() *encoding.Decoder {
	return &encoding.Decoder{Transformer: makeDecoder(&{{.LowerName}}ToUnicode)}
}

func (e *{{.LowerName}}Encoding) NewEncoder() *encoding.Encoder {
	return &encoding.Encoder{Transformer: makeEncoder(&{{.LowerName}}ToUnicode, {{.LowerName}}FromUnicode)}
}

func (e *{{.LowerName}}Encoding) String() string {
	return "{{$.EncodingPrefix}}{{.GoName}}"
}
{{end}}
`

// TemplateData holds data for template rendering.
type TemplateData struct {
	PackageName    string
	VendorName     string
	SourceURL      string
	EncodingPrefix string
	Encodings      []EncodingTemplateData
}

// EncodingTemplateData holds data for a single encoding.
type EncodingTemplateData struct {
	Name        string // Original name (e.g., "ROMAN")
	GoName      string // Go-style name (e.g., "Roman")
	LowerName   string // Lowercase name for unexported identifiers
	ToUnicode   [256]rune
	FromUnicode []MappingData
}

// MappingData holds a single mapping for the reverse lookup.
type MappingData struct {
	Byte    byte
	Unicode rune
	Name    string
}

func generateTablesFile(outputDir string, encodings []EncodingData, cfg VendorConfig) error {
	data := TemplateData{
		PackageName:    cfg.PackageName,
		VendorName:     cfg.VendorName,
		SourceURL:      cfg.SourceURL,
		EncodingPrefix: cfg.EncodingPrefix,
		Encodings:      make([]EncodingTemplateData, 0, len(encodings)),
	}

	for _, enc := range encodings {
		tplData := prepareEncodingData(enc, cfg)
		data.Encodings = append(data.Encodings, tplData)
	}

	funcMap := template.FuncMap{
		"mod": func(a, b int) int { return a % b },
		"add": func(a, b int) int { return a + b },
		"sub": func(a, b int) int { return a - b },
		"eq":  func(a, b int) bool { return a == b },
	}

	tmpl, err := template.New("tables").Funcs(funcMap).Parse(tablesTemplate)
	if err != nil {
		return fmt.Errorf("parse template: %w", err)
	}

	outPath := filepath.Join(outputDir, "tables_generated.go")
	f, err := os.Create(outPath)
	if err != nil {
		return fmt.Errorf("create file: %w", err)
	}
	defer f.Close()

	if err := tmpl.Execute(f, data); err != nil {
		return fmt.Errorf("execute template: %w", err)
	}

	fmt.Printf("Generated: %s\n", outPath)
	return nil
}

func generateEncodingsFile(outputDir string, encodings []EncodingData, cfg VendorConfig) error {
	data := TemplateData{
		PackageName:    cfg.PackageName,
		VendorName:     cfg.VendorName,
		SourceURL:      cfg.SourceURL,
		EncodingPrefix: cfg.EncodingPrefix,
		Encodings:      make([]EncodingTemplateData, 0, len(encodings)),
	}

	for _, enc := range encodings {
		tplData := prepareEncodingData(enc, cfg)
		data.Encodings = append(data.Encodings, tplData)
	}

	tmpl, err := template.New("encodings").Parse(encodingsTemplate)
	if err != nil {
		return fmt.Errorf("parse template: %w", err)
	}

	outPath := filepath.Join(outputDir, "encodings_generated.go")
	f, err := os.Create(outPath)
	if err != nil {
		return fmt.Errorf("create file: %w", err)
	}
	defer f.Close()

	if err := tmpl.Execute(f, data); err != nil {
		return fmt.Errorf("execute template: %w", err)
	}

	fmt.Printf("Generated: %s\n", outPath)
	return nil
}

func prepareEncodingData(enc EncodingData, cfg VendorConfig) EncodingTemplateData {
	goName := toGoName(enc.Name, cfg.NameReplacements)
	lowerName := strings.ToLower(string(goName[0])) + goName[1:]

	// Initialize ToUnicode with replacement character for unmapped bytes (0x80-0xFF)
	// and identity mapping for ASCII range (0x00-0x7F) since most legacy
	// encodings are ASCII-compatible
	var toUnicode [256]rune
	for i := range toUnicode {
		if i < 0x80 {
			toUnicode[i] = rune(i) // ASCII identity mapping
		} else {
			toUnicode[i] = utf8.RuneError // Unicode replacement character
		}
	}

	// Build FromUnicode map, deduplicating by Unicode code point
	// (some encodings like KEYBOARD have multiple bytes mapping to the same Unicode)
	seenUnicode := make(map[rune]bool)
	var fromUnicode []MappingData
	for _, m := range enc.Mappings {
		toUnicode[m.Byte] = m.Unicode
		// Only add to reverse map if we haven't seen this Unicode code point
		if !seenUnicode[m.Unicode] {
			seenUnicode[m.Unicode] = true
			fromUnicode = append(fromUnicode, MappingData{
				Byte:    m.Byte,
				Unicode: m.Unicode,
				Name:    m.Name,
			})
		}
	}

	// Sort FromUnicode by Unicode code point
	sort.Slice(fromUnicode, func(i, j int) bool {
		return fromUnicode[i].Unicode < fromUnicode[j].Unicode
	})

	return EncodingTemplateData{
		Name:        enc.Name,
		GoName:      goName,
		LowerName:   lowerName,
		ToUnicode:   toUnicode,
		FromUnicode: fromUnicode,
	}
}

// toGoName converts an encoding name to a Go-style exported name.
// e.g., "ROMAN" -> "Roman", "CENTEURO" -> "CentEuro"
// The replacements map allows vendor-specific name overrides.
func toGoName(name string, replacements map[string]string) string {
	nameLower := strings.ToLower(name)

	// Check for vendor-specific replacements
	if replacements != nil {
		if replacement, ok := replacements[nameLower]; ok {
			return replacement
		}
	}

	// Title case the first letter
	runes := []rune(nameLower)
	if len(runes) > 0 {
		runes[0] = unicode.ToUpper(runes[0])
	}

	return string(runes)
}
